          EPIUR:{objetive:"Obtenez 1 Fragment d'Épigraph UR",resource:"Ouvrez le Coffre des Épigraphes"},
          HERBS:{objetive:"Récoltez 60 Herbes, toute la journée",resource:"Jardin d'Herbes Nv.10 > 8H"},
